const listOverdueUnnotifiedLoans = `-- name: ListOverdueUnnotifiedLoans :many
SELECT id, asset_id, borrower_id, ticket_id, lent_by, started_on, return_by, returned_on, overdue_notified_on, created_at, returned_by, return_note FROM inventory.loans
WHERE returned_on IS NULL AND return_by < $1::date AND overdue_notified_on IS NULL
ORDER BY return_by, id
LIMIT $2
FOR UPDATE SKIP LOCKED
`

type ListOverdueUnnotifiedLoansParams struct {
	Today pgtype.Date
	Lim   int32
}

// Khoản quá hạn chưa báo, khoá để hai lần quét cùng lúc không báo trùng
func (q *Queries) ListOverdueUnnotifiedLoans(ctx context.Context, arg ListOverdueUnnotifiedLoansParams) ([]InventoryLoan, error) {
	rows, err := q.db.Query(ctx, listOverdueUnnotifiedLoans, arg.Today, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InventoryLoan{}
	for rows.Next() {
		var i InventoryLoan
		if err := rows.Scan(
			&i.ID,
			&i.AssetID,
			&i.BorrowerID,
			&i.TicketID,
			&i.LentBy,
			&i.StartedOn,
			&i.ReturnBy,
			&i.ReturnedOn,
			&i.OverdueNotifiedOn,
			&i.CreatedAt,
			&i.ReturnedBy,
			&i.ReturnNote,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markLoanOverdueNotified = `-- name: MarkLoanOverdueNotified :exec
UPDATE inventory.loans SET overdue_notified_on = $1::date WHERE id = $2
`

type MarkLoanOverdueNotifiedParams struct {
	Today pgtype.Date
	ID    uuid.UUID
}

func (q *Queries) MarkLoanOverdueNotified(ctx context.Context, arg MarkLoanOverdueNotifiedParams) error {
	_, err := q.db.Exec(ctx, markLoanOverdueNotified, arg.Today, arg.ID)
	return err
}

